#include <iostream>

int cajas_para(int piezas) { return piezas / 4; }

int main() {
    std::cout << cajas_para(0) << ":" << cajas_para(5)
              << ":" << cajas_para(17);
    return 0;
}

#include "envio/cajas.h"
#include <iostream>

bool comprobar(int piezas, int esperado) {
    const int obtenido{cajas_para(piezas)};
    const bool coincide{obtenido == esperado};
    std::cout << "piezas=" << piezas << " expected=" << esperado
              << " actual=" << obtenido << " ";
    if (coincide) { std::cout << "OK\n"; }
    else { std::cout << "FAIL\n"; }
    return coincide;
}

int main() {
    bool correcto{true};
    if (!comprobar(0, 0)) { correcto = false; }
    if (!comprobar(4, 1)) { correcto = false; }
    if (!comprobar(8, 2)) { correcto = false; }
    if (!comprobar(20, 5)) { correcto = false; }
    if (!correcto) {
        std::cout << "Suite: FAIL\n";
        return 1;
    }
    std::cout << "Suite: OK\n";
    return 0;
}

